 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = []
    for row in grid:
        for color in row:
            if color and color not in colors:
                colors.append(color)
    colors.sort(key=lambda color: min((r, c) for r in range(h) for c in range(w) if grid[r][c] == color))
    out = [[0] * w for _ in range(h)]
    top = left = 0
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
        r1, c1 = max(r for r, c in cells), max(c for r, c in cells)
        for r, c in cells:
            rr, cc = top + r - r0, left + c - c0
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
        top += r1 - r0
        left += c1 - c0
    return out
